 axs[0,1].set(xlabel='Epoch',ylabel='Scaled return MSE',yscale='log',title='Solid training and dashed validation');axs[0,1].legend(fontsize=6,ncol=3)
 axs[1,0].hist((arr[name]-arr['actual']).ravel(),bins=50);axs[1,0].set(xlabel='Prediction minus actual USDT',ylabel='Seed observations',title='Correlated seed error distribution')
 gg=np.stack(gates);axs[1,1].plot(times,gg.mean(axis=0),lw=.8);axs[1,1].fill_between(times,gg.min(axis=0),gg.max(axis=0),alpha=.2);axs[1,1].set(ylim=(0,1.05),ylabel='Raw gate',title='Mean and range across seeds');axs[1,1].tick_params(axis='x',rotation=25);fig.tight_layout();fig.savefig(out/'DIAGNOSTICS.png',dpi=170);plt.close(fig)
 d=newdoc('XRP '+gateword+' news correction experiment');d.add_paragraph(f'The {gateword} correction has mean validation RMSE {row.rmse_mean:.6f} USDT, {row.rmse_improvement_vs_E0_percent:.3f}% lower than frozen technical E0, but {-row.rmse_improvement_vs_E1B_percent:.3f}% higher than compact direct news E1B. The correction does not displace E1B as the best validation configuration. No statistically robust advantage is established by the adjusted intervals.')
 d.add_heading('Matched data and architecture',1);d.add_paragraph(protocol);d.add_paragraph(training_e4);d.add_paragraph(f'The correction receives the same eight news features as E3: direct sentiment, specificity, stance, uncertainty, hourly presence, capped hours since news, six-hour equation sentiment and no-relevant-news flag. There are {cfg["trainable_parameters"]:,} trainable and 564,353 frozen parameters ({cfg["trainable_parameters"]+564353:,} total). No attention or technical fine-tuning is used. Correction input scaling is fitted only on training-window rows; the technical target scaler is reused. Total correction fitting time was {ss.training_seconds.sum()/60:.2f} minutes, excluding cached technical inference.')
 d.add_heading('Five seed validation results',1);table(d,['Seed','Epoch','RMSE','MAE','R squared','Direction'],[[int(r.seed),int(r.selected_epoch),f'{r.rmse:.6f}',f'{r.mae:.6f}',f'{r.r2:.6f}',f'{100*r.directional_accuracy:.2f}%'] for _,r in ss.iterrows()]);d.add_paragraph(f'Mean ± sample SD: RMSE {row.rmse_mean:.6f} ± {row.rmse_std:.6f}; MAE {row.mae_mean:.6f} ± {row.mae_std:.6f}; R squared {row.r2_mean:.6f} ± {row.r2_std:.6f}; direction {100*row.directional_accuracy_mean:.2f}% ± {100*row.directional_accuracy_std:.2f} percentage points. Persistence RMSE {pers["rmse"]:.6f}; relative RMSE improvement {row.rmse_improvement_vs_persistence_percent:.3f}%. Persistence predicts no change, so its direction score is not an up/down skill benchmark.')
 pageheading(d,'Correction equations and statistical comparison');d.add_paragraph('The GRU encodes the 30-hour news sequence into h(t). The correction head starts at zero. The same seed-matched frozen technical forecast is used throughout training and validation. m(t) is 1 when the trailing 48-hour archive has positive specificity-weighted news mass, otherwise 0. For the ungated model, g(t)=1. For the gated model, g(t) is learned from h(t).');equation(d,'Δ(t) = WΔ h(t) + bΔ; g(t) = sigmoid(Wg h(t) + bg)');equation(d,'r̂(t) = r̂tech(t) + m(t) g(t) Δ(t)');equation(d,'P̂(t+24) = P(t) exp(r̂(t))');equation(d,'loss = MSE(scaled r̂, scaled r) + 0.001 mean[(a m g Δ)²]');d.add_paragraph('Here a is the training-fitted target scale factor. Adam additionally applies weight decay 0.0001. The penalty discourages large corrections; checkpoint selection uses unpenalised validation MSE. Turning the correction off reproduces E0 exactly; so does forcing m=0. These invariance checks passed on every trained checkpoint.')
 d.add_paragraph(stat_e4);cc=ci[ci.candidate.eq(name)&ci.block_hours.eq(72)&ci.reference.isin(['E0','E1B','E3'])];table(d,['Reference','Risk difference','Adjusted interval'],[[r.reference,f'{r.rmse_risk_difference:+.6f}',f'[{r.ci_adjusted_low:+.6f}, {r.ci_adjusted_high:+.6f}]'] for _,r in cc.iterrows()]);d.add_paragraph('All displayed intervals include zero. Small numerical gains over E0 are not evidence of a reliable market-wide improvement.')
 d.add_heading('News availability and gate behaviour',1);d.add_paragraph('All 2,136 validation origins have eligible news in the preceding 48 hours; there are zero inactive-mask observations. The no-news safeguard was verified by explicitly forcing the mask off, but its forecasting performance cannot be estimated in a naturally inactive validation subgroup. Current-hour article presence is a different measure: an hour without a new article may still have eligible older news.')
 sub=g[g.news_group.isin(['new_article_hour','no_new_article_hour'])].groupby('news_group').agg(n=('n','first'),rmse=('rmse','mean'),technical_rmse=('technical_rmse','mean'),gate=('raw_gate_mean','mean'),correction=('mean_abs_price_correction','mean')).reset_index();table(d,['Current hour','Origins','RMSE','E0 RMSE','Mean gate'],[[r.news_group.replace('_',' '),int(r.n),f'{r.rmse:.6f}',f'{r.technical_rmse:.6f}',f'{r.gate:.3f}'] for _,r in sub.iterrows()]);d.add_paragraph('Subgroup values average the same five seeds and are descriptive, not separate selection criteria. A learned gate is not a causal attribution or a probability that news moves prices.')
 pageheading(d,'Forecast and learning diagnostics');pic(d,out/'DIAGNOSTICS.png','Prediction means and gate ranges are descriptive seed summaries, not a separately evaluated ensemble. Loss curves use unpenalised MSE. Errors across seeds are correlated.');d.add_heading('Interpretation and limitations',1);d.add_paragraph(limits_e4);d.add_paragraph('The ungated variant has the lower E4 mean validation RMSE. The learned gate provides no demonstrated incremental benefit in this experiment. Small corrections to a fixed baseline can reduce average error, but the present results do not show that adaptive gating is preferable to direct news inputs.');d.add_heading('Reproducibility',1);d.add_paragraph('PROTOCOL.json and FROZEN_MANIFEST.json preserve settings, data, code and source hashes. Every seed retains checkpoint, history, predictions, selected epoch, metrics and log. Fresh inference verified all ten correction checkpoints and all five technical caches on training and validation origins. Prior reports and models remain unchanged. Run code/verify_and_analyse.py with the research ML Python and code/build_reports.py with bundled document Python. Stop before additional fitting or final evaluation.');save_doc(d,out/'SCIENTIFIC_REPORT.docx')
